CREATE TABLE project (
    Avatar_URL VARCHAR(255),
    Project_ID INTEGER PRIMARY KEY,
    Project_Name VARCHAR(255)
);

CREATE TABLE API (
    Access_Path VARCHAR(255),
    Belonging_Project INTEGER NOT NULL,
    Identifier INTEGER PRIMARY KEY,
    Name VARCHAR(255),
    FOREIGN KEY (Belonging_Project) REFERENCES project(Project_ID)
);

CREATE TABLE API_Response_Record (
    API_Identifier INTEGER NOT NULL,
    Call_Time DATETIME,
    Response_Time DATETIME,
    PRIMARY KEY (API_Identifier, Call_Time),
    FOREIGN KEY (API_Identifier) REFERENCES API(Identifier)
);
